__host__ __device__ std::uint16_t float_to_bf16(float value) {
    union { float f; std::uint32_t u; } v{value};
    if ((v.u & 0x7fffffffu) > 0x7f800000u) return 0x7fc0u;
    const std::uint32_t bias = 0x7fffu + ((v.u >> 16u) & 1u);
    v.u += bias;
    return static_cast<std::uint16_t>(v.u >> 16u);
}
```

### Detailed Explanation

This function converts a 32-bit IEEE 754 single-precision floating-point number (`float`) into a 16-bit Brain Float (BF16) format. BF16 is a reduced-precision format that keeps the same 8-bit exponent as FP32 but truncates the mantissa to 7 bits (plus 1 sign bit
